import{_ as i,c as t,o as a,a5 as l}from"./chunks/framework.BXgPSHrU.js";const d=JSON.parse('{"title":"🚀 InsightCosmos -- Capstone Full Writeup（繁體中文版）","description":"","frontmatter":{},"headers":[],"relativePath":"project/InsightCosmos_Full_Writeup_FULL_zh_TW.md","filePath":"project/InsightCosmos_Full_Writeup_FULL_zh_TW.md","lastUpdated":1764825942000}'),o={name:"project/InsightCosmos_Full_Writeup_FULL_zh_TW.md"};function n(r,e,s,h,u,g){return a(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="🚀-insightcosmos-capstone-full-writeup-繁體中文版" tabindex="-1">🚀 InsightCosmos -- Capstone Full Writeup（繁體中文版） <a class="header-anchor" href="#🚀-insightcosmos-capstone-full-writeup-繁體中文版" aria-label="Permalink to &quot;🚀 InsightCosmos -- Capstone Full Writeup（繁體中文版）&quot;">​</a></h1><blockquote><p><strong>GitHub Repository</strong>: <a href="https://github.com/phileiny/InsightCosmos" target="_blank" rel="noreferrer">https://github.com/phileiny/InsightCosmos</a></p></blockquote><h2 id="_1-引言與靈感來源-introduction-inspiration" tabindex="-1">1. 引言與靈感來源（Introduction &amp; Inspiration） <a class="header-anchor" href="#_1-引言與靈感來源-introduction-inspiration" aria-label="Permalink to &quot;1. 引言與靈感來源（Introduction &amp; Inspiration）&quot;">​</a></h2><p>AI 與機器人領域的進展速度，已經快到任何人都無法靠手動方式完全追蹤。 每天都有來自數十個來源的新論文、新模型、新框架、新突破與新產業動態湧現。</p><p>對一位全職工程師或研究員來說，保持資訊更新已不再是「閱讀能力」的問題------<br> 而是<strong>資訊超載</strong>的問題。</p><p>我打造 InsightCosmos，是為了回答一個簡單的問題：</p><p><strong>如果有一個自主 AI agent 能每天持續掃描整個 AI 宇宙，並只把我真正需要知道的那些資訊整理給我------會是什麼樣子？</strong></p><p>InsightCosmos 是一套個人智慧系統，充當多代理人的觀測站，<br> 替我處理資訊，並產出具結構化且可行動的洞察。</p><hr><h2 id="_2-專案概述-insightcosmos-能做什麼-project-overview" tabindex="-1">2. 專案概述 --- InsightCosmos 能做什麼（Project Overview） <a class="header-anchor" href="#_2-專案概述-insightcosmos-能做什麼-project-overview" aria-label="Permalink to &quot;2. 專案概述 --- InsightCosmos 能做什麼（Project Overview）&quot;">​</a></h2><p>InsightCosmos 是一套 <strong>全自動（fully autonomous）</strong> 的 AI 情報處理管線。</p><h3 id="daily-每日" tabindex="-1">Daily（每日） <a class="header-anchor" href="#daily-每日" aria-label="Permalink to &quot;Daily（每日）&quot;">​</a></h3><ul><li>從 RSS 與搜尋結果抓取新資訊\\</li><li>使用 LLM 推理分析內容\\</li><li>評分與抽取洞察\\</li><li>儲存至向量記憶（Vector Memory）\\</li><li>產生《每日情報摘要》\\</li><li>透過 Email 寄送</li></ul><h3 id="weekly-每週" tabindex="-1">Weekly（每週） <a class="header-anchor" href="#weekly-每週" aria-label="Permalink to &quot;Weekly（每週）&quot;">​</a></h3><ul><li>取回過去 7 天的完整資料\\</li><li>執行嵌入聚類（clustering）\\</li><li>分析趨勢（trend analysis）\\</li><li>產生《每週深度報告》\\</li><li>以 Email 寄送</li></ul><p><strong>部署之後無需手動操作。</strong><br> InsightCosmos 是一個永遠運轉的「個人智慧宇宙」。</p><hr><h2 id="_3-系統架構-google-ai-agent-風格" tabindex="-1">3. 系統架構（Google AI Agent 風格） <a class="header-anchor" href="#_3-系統架構-google-ai-agent-風格" aria-label="Permalink to &quot;3. 系統架構（Google AI Agent 風格）&quot;">​</a></h2><p>InsightCosmos 採用 Google 的 Agentic System 原則：</p><ul><li><strong>Autonomous behavior（自主行為）</strong></li><li><strong>Tool use（工具調用）</strong></li><li><strong>Reasoning &amp; reflection（推理與反思）</strong></li><li><strong>Memory-based decisions（基於記憶決策）</strong></li><li><strong>Goal-oriented execution（目標導向執行）</strong></li></ul><h3 id="系統概念流程-pipeline" tabindex="-1">系統概念流程（Pipeline） <a class="header-anchor" href="#系統概念流程-pipeline" aria-label="Permalink to &quot;系統概念流程（Pipeline）&quot;">​</a></h3><pre><code>┌───────────────────────────────┐
│       Daily / Weekly Runner    │
└───────────────┬───────────────┘
                ↓
┌───────────────────────────────┐
│          Scout Agent           │
│   - RSS &amp; Search collection    │
│   - Deduplication via vectors  │
└───────────────┬───────────────┘
                ↓
┌───────────────────────────────┐
│          Analyst Agent         │
│   - LLM reasoning              │
│   - TL;DR + insights           │
│   - Relevance scoring          │
│   - Reflection for quality     │
│   - Embedding creation         │
└───────────────┬───────────────┘
                ↓
┌───────────────────────────────┐
│        Memory Universe         │
│   - SQLite structured storage  │
│   - Embedding vector memory    │
└───────────────┬───────────────┘
                ↓
┌───────────────────────────────┐
│          Curator Agent         │
│   - Daily Digest               │
│   - Weekly Deep Report         │
└───────────────┬───────────────┘
                ↓
┌───────────────────────────────┐
│         Email Delivery         │
└───────────────────────────────┘
</code></pre><hr><h2 id="_4-代理人分工-agents-breakdown" tabindex="-1">4. 代理人分工（Agents Breakdown） <a class="header-anchor" href="#_4-代理人分工-agents-breakdown" aria-label="Permalink to &quot;4. 代理人分工（Agents Breakdown）&quot;">​</a></h2><hr><h3 id="_4-1-scout-agent-探索-discovery" tabindex="-1">4.1 <strong>Scout Agent --- 探索（Discovery）</strong> <a class="header-anchor" href="#_4-1-scout-agent-探索-discovery" aria-label="Permalink to &quot;4.1 **Scout Agent --- 探索（Discovery）**&quot;">​</a></h3><p>Scout Agent 的任務是：</p><ul><li>蒐集 RSS 來源\\</li><li>Google Search 搜尋新主題\\</li><li>抽取 metadata\\</li><li>使用向量相似度做重複內容過濾（deduplication）</li></ul><p>確保只有高價值、不重複的記事進入系統。</p><hr><h3 id="_4-2-analyst-agent-理解與推理-understanding-reasoning" tabindex="-1">4.2 <strong>Analyst Agent --- 理解與推理（Understanding &amp; Reasoning）</strong> <a class="header-anchor" href="#_4-2-analyst-agent-理解與推理-understanding-reasoning" aria-label="Permalink to &quot;4.2 **Analyst Agent --- 理解與推理（Understanding &amp; Reasoning）**&quot;">​</a></h3><p>對每個蒐集到的項目，Analyst Agent 會：</p><ul><li>閱讀內容\\</li><li>解構： <ul><li>關鍵技術概念\\</li><li>為何重要\\</li><li>與我的興趣或研究方向的相關性\\</li></ul></li><li>進行 CoT 推理\\</li><li>執行反思（reflection）強化品質\\</li><li>產生 Insight Score（0--10 分）\\</li><li>建立向量嵌入</li></ul><hr><h3 id="_4-3-curator-agent-綜整-synthesis" tabindex="-1">4.3 <strong>Curator Agent --- 綜整（Synthesis）</strong> <a class="header-anchor" href="#_4-3-curator-agent-綜整-synthesis" aria-label="Permalink to &quot;4.3 **Curator Agent --- 綜整（Synthesis）**&quot;">​</a></h3><p>Curator Agent 負責輸出最終的資訊：</p><h4 id="daily-digest-每日摘要" tabindex="-1">Daily Digest（每日摘要） <a class="header-anchor" href="#daily-digest-每日摘要" aria-label="Permalink to &quot;Daily Digest（每日摘要）&quot;">​</a></h4><ul><li>挑選前 5--10 筆最重要資訊\\</li><li>生成具洞察、可行動的敘述\\</li><li>以 Email 格式化成 Markdown</li></ul><h4 id="weekly-deep-report-每週深度報告" tabindex="-1">Weekly Deep Report（每週深度報告） <a class="header-anchor" href="#weekly-deep-report-每週深度報告" aria-label="Permalink to &quot;Weekly Deep Report（每週深度報告）&quot;">​</a></h4><ul><li>回溯過去 7 天的記憶\\</li><li>嵌入聚類找出趨勢\\</li><li>分析 2--3 個主要的每週主題\\</li><li>提供個人化建議</li></ul><p>Curator Agent 的存在，讓系統從單純自動化變成<strong>真正有智慧的編輯器</strong>。</p><hr><h2 id="_5-工具使用-tool-use" tabindex="-1">5. 工具使用（Tool Use） <a class="header-anchor" href="#_5-工具使用-tool-use" aria-label="Permalink to &quot;5. 工具使用（Tool Use）&quot;">​</a></h2><p>InsightCosmos 展示多種工具的協作：</p><p>工具 用途</p><hr><p>HTTP / RSS Fetcher 抓取內容 Search Tool 尋找新興 AI 趨勢 Embedding Tool 相似搜尋與聚類 Email Tool 寄送報告 SQLite 輕量結構化記憶庫</p><p>符合 Capstone 必要條件：<br><strong>LLM + Tools + Memory = 自主智慧循環</strong></p><hr><h2 id="_6-記憶宇宙-memory-universe" tabindex="-1">6. 記憶宇宙（Memory Universe） <a class="header-anchor" href="#_6-記憶宇宙-memory-universe" aria-label="Permalink to &quot;6. 記憶宇宙（Memory Universe）&quot;">​</a></h2><p>InsightCosmos 的記憶由兩部分組成：</p><h3 id="_1-sqlite-結構化資料庫" tabindex="-1">1. SQLite 結構化資料庫 <a class="header-anchor" href="#_1-sqlite-結構化資料庫" aria-label="Permalink to &quot;1. SQLite 結構化資料庫&quot;">​</a></h3><p>儲存：</p><ul><li>文章資料\\</li><li>分析結果\\</li><li>每日/每週輸出\\</li><li>中繼資訊</li></ul><h3 id="_2-向量記憶-embedding-vector-store" tabindex="-1">2. 向量記憶（Embedding Vector Store） <a class="header-anchor" href="#_2-向量記憶-embedding-vector-store" aria-label="Permalink to &quot;2. 向量記憶（Embedding Vector Store）&quot;">​</a></h3><p>用於：</p><ul><li>文件去重\\</li><li>主題聚類\\</li><li>趨勢辨識\\</li><li>每週報告分析</li></ul><p>記憶不只是存資料，而是讓系統能<strong>基於過去做推理</strong>。</p><hr><h2 id="_7-範例輸出-sample-outputs" tabindex="-1">7. 範例輸出（Sample Outputs） <a class="header-anchor" href="#_7-範例輸出-sample-outputs" aria-label="Permalink to &quot;7. 範例輸出（Sample Outputs）&quot;">​</a></h2><hr><h3 id="daily-digest-範例" tabindex="-1">Daily Digest 範例 <a class="header-anchor" href="#daily-digest-範例" aria-label="Permalink to &quot;Daily Digest 範例&quot;">​</a></h3><p><strong>Top AI &amp; Robotics Intelligence --- Feb 2025</strong></p><ol><li><strong>OpenAI 發表新一代多模態機器人模型</strong><ul><li>核心概念：操作 + 視覺 + 規劃的統一架構\\</li><li>為何重要：朝汎用機器人前進的大步\\</li><li>與我研究的相關性：高度一致</li></ul></li><li><strong>Google 推出 agentic workflow APIs</strong><ul><li>越來越接近多代理系統的標準化<br> ...</li></ul></li></ol><hr><h3 id="weekly-deep-report-範例" tabindex="-1">Weekly Deep Report 範例 <a class="header-anchor" href="#weekly-deep-report-範例" aria-label="Permalink to &quot;Weekly Deep Report 範例&quot;">​</a></h3><p><strong>本週 AI 情報趨勢</strong></p><h4 id="趨勢-1-agentic-robotics-integration" tabindex="-1">趨勢 1 --- Agentic Robotics Integration <a class="header-anchor" href="#趨勢-1-agentic-robotics-integration" aria-label="Permalink to &quot;趨勢 1 --- Agentic Robotics Integration&quot;">​</a></h4><ul><li>LLM 推理與 embodied control 加速融合\\</li><li>顯著影響新論文的方向集中於自主規劃</li></ul><h4 id="趨勢-2-模型統一化" tabindex="-1">趨勢 2 --- 模型統一化 <a class="header-anchor" href="#趨勢-2-模型統一化" aria-label="Permalink to &quot;趨勢 2 --- 模型統一化&quot;">​</a></h4><ul><li>各大科技公司在押注 multi-task / multi-modal 統一架構</li></ul><p><strong>下週建議行動</strong>\\</p><ul><li>研究 Embodied Agents benchmark\\</li><li>在 InsightCosmos 內嘗試建 prototype evaluator</li></ul><hr><h2 id="_8-成果與影響-results-impact" tabindex="-1">8. 成果與影響（Results &amp; Impact） <a class="header-anchor" href="#_8-成果與影響-results-impact" aria-label="Permalink to &quot;8. 成果與影響（Results &amp; Impact）&quot;">​</a></h2><p>InsightCosmos 成功解決了真實的資訊痛點：</p><p>✔ 免去每天掃描大量來源<br> ✔ 收到的都是洞察，而不是雜訊<br> ✔ 每週研究時間從數小時 → 幾分鐘<br> ✔ 系統完全自動化、零維護<br> ✔ agent 逐漸成為我的「外掛大腦」</p><p>InsightCosmos 將資訊超載轉換為<strong>策略優勢</strong>。</p><hr><h2 id="_9-未來發展-future-work" tabindex="-1">9. 未來發展（Future Work） <a class="header-anchor" href="#_9-未來發展-future-work" aria-label="Permalink to &quot;9. 未來發展（Future Work）&quot;">​</a></h2><h3 id="v2-intelligent-universe-智慧宇宙" tabindex="-1">v2 --- Intelligent Universe（智慧宇宙） <a class="header-anchor" href="#v2-intelligent-universe-智慧宇宙" aria-label="Permalink to &quot;v2 --- Intelligent Universe（智慧宇宙）&quot;">​</a></h3><ul><li>自動計算來源品質評分\\</li><li>個人化主題偏好學習\\</li><li>透過向量演化的興趣模型\\</li><li>視覺化知識圖 Nebula Map</li></ul><h3 id="v3-enterprise-universe-企業宇宙" tabindex="-1">v3 --- Enterprise Universe（企業宇宙） <a class="header-anchor" href="#v3-enterprise-universe-企業宇宙" aria-label="Permalink to &quot;v3 --- Enterprise Universe（企業宇宙）&quot;">​</a></h3><ul><li>多使用者版本\\</li><li>Hunter / Learner / Coordinator Agents\\</li><li>組織級情報管線\\</li><li>Intelligence-as-a-Service 平台</li></ul><p>InsightCosmos 將逐步成為一個完整的 AI Intelligence 生態系統。</p><hr><h2 id="_10-結論-conclusion" tabindex="-1">10. 結論（Conclusion） <a class="header-anchor" href="#_10-結論-conclusion" aria-label="Permalink to &quot;10. 結論（Conclusion）&quot;">​</a></h2><p>InsightCosmos 並不是一支自動化腳本------<br> 它是一個具記憶、能推理、可使用工具、可自主運作的 AI Agent 系統。</p><p>它展現出：</p><ul><li>多代理架構\\</li><li>推理與反思能力\\</li><li>工具協作能力\\</li><li>基於記憶的智慧行為\\</li><li>完整自主的端到端管線</li></ul><p>InsightCosmos 展示了 AI agent 的未來：</p><p><strong>不再是被動助手，而是主動的智慧夥伴。</strong></p>`,92)])])}const c=i(o,[["render",n]]);export{d as __pageData,c as default};
